// What: assembles the one state a reloaded page asks for.
// Why: consent and an open session live in main, and the page must not guess either after a reload.
// Removed: the Start button would stay disabled while main still holds consent and the camera.
import { appStateSchema, type AppSessionState, type AppState, type ConsentState } from '../shared/contracts.js';

export interface AppStateSources {
  consent(): ConsentState;
  session(): AppSessionState;
}

/** Pure seam so the reload contract is tested without Electron or a camera. */
export function readAppState(sources: AppStateSources): AppState {
  return appStateSchema.parse({
    consent: sources.consent(),
    session: sources.session(),
  });
}

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { readAppState } from './app-state.js';

describe('readAppState', () => {
  it('reports consent and a live session so a reload can resume the sensing screen', () => {
    const state = readAppState({
      consent: () => ({ granted: true, cameraAllowed: true }),
      session: () => ({
        active: true,
        sessionId: 'session-1',
        startedAtEpochMs: 1_000,
        betweenGames: true,
      }),
    });
    assert.equal(state.consent.granted, true);
    assert.equal(state.session.active, true);
    assert.equal(state.session.sessionId, 'session-1');
    assert.equal(state.session.betweenGames, true);
  });

  it('reports consent without inventing a session', () => {
    const state = readAppState({
      consent: () => ({ granted: true, cameraAllowed: true }),
      session: () => ({
        active: false,
        sessionId: null,
        startedAtEpochMs: null,
        betweenGames: false,
      }),
    });
    assert.equal(state.session.active, false);
    assert.equal(state.session.sessionId, null);
  });

  it('refuses a self-contradictory session snapshot', () => {
    assert.throws(() =>
      readAppState({
        consent: () => ({ granted: false, cameraAllowed: false }),
        session: () => ({
          active: false,
          sessionId: 'session-1',
          startedAtEpochMs: 1_000,
          betweenGames: false,
        }),
      }),
    );
  });
});

