import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import {
  UNKNOWN_FRAMING,
  VALIDATION,
  framingFromValidation,
  framingReady,
  framingStatusText,
} from './framing.js';

describe('framing checks', () => {
  it('passes all three checks only on the SDK ok code', () => {
    assert.deepEqual(framingFromValidation(VALIDATION.ok), {
      face: 'pass',
      chest: 'pass',
      light: 'pass',
    });
    assert.equal(framingReady(framingFromValidation(VALIDATION.ok)), true);
    assert.equal(framingReady(UNKNOWN_FRAMING), false);
  });

  it('marks the chest as the failing check while keeping the face pass', () => {
    const checks = framingFromValidation(VALIDATION.chestNotVisible);
    assert.deepEqual(checks, { face: 'pass', chest: 'fail', light: 'unknown' });
    assert.equal(framingReady(checks), false);
  });

  it('marks the face as failing for a face code', () => {
    for (const code of [
      VALIDATION.noFaceFound,
      VALIDATION.multipleFacesFound,
      VALIDATION.faceNotCentered,
      VALIDATION.faceSizeOutOfRange,
      VALIDATION.faceTooClose,
      VALIDATION.faceTooFar,
      VALIDATION.faceTooHigh,
      VALIDATION.faceTooLow,
      VALIDATION.faceNotForward,
    ]) {
      assert.equal(framingFromValidation(code).face, 'fail', String(code));
      assert.equal(framingFromValidation(code).chest, 'unknown', String(code));
    }
  });

  it('marks light as failing for dark or bright frames', () => {
    for (const code of [VALIDATION.tooDark, VALIDATION.tooBright]) {
      assert.deepEqual(framingFromValidation(code), {
        face: 'unknown',
        chest: 'unknown',
        light: 'fail',
      });
    }
  });

  it('does not borrow a pass for tuning, motion, or an unknown code', () => {
    for (const code of [VALIDATION.cameraTuning, VALIDATION.frameRateTooLow, VALIDATION.excessiveMotion, 999]) {
      assert.deepEqual(framingFromValidation(code), UNKNOWN_FRAMING);
    }
  });

  it('gives every state a text label, never colour alone', () => {
    assert.equal(framingStatusText('pass'), 'OK');
    assert.equal(framingStatusText('fail'), 'Fix');
    assert.equal(framingStatusText('unknown'), 'Waiting');
  });
});

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import type { FramingChecks } from './framing.js';
import { keyStatusFromChecks, setupGate, type SetupGateInput } from './setup.js';

const readyFraming: FramingChecks = { face: 'pass', chest: 'pass', light: 'pass' };
const waitingFraming: FramingChecks = { face: 'unknown', chest: 'unknown', light: 'unknown' };

function input(overrides: Partial<SetupGateInput> = {}): SetupGateInput {
  return {
    consent: true,
    keyStatus: 'present',
    keyDetail: 'Present (value not shown).',
    preview: 'running',
    framing: readyFraming,
    ...overrides,
  };
}

describe('setup gate', () => {
  it('starts only when consent, the key, the preview, and all three checks pass', () => {
    assert.deepEqual(setupGate(input()), { canStart: true, reasons: [] });
  });

  it('names consent first', () => {
    const gate = setupGate(input({ consent: false }));
    assert.equal(gate.canStart, false);
    assert.deepEqual(gate.reasons, ['Allow the camera to continue.']);
  });

  it('waits while the key is being checked, then blocks when it is missing', () => {
    assert.match(setupGate(input({ keyStatus: 'loading' })).reasons[0], /Checking/);
    const missing = setupGate(
      input({
        keyStatus: 'missing',
        keyDetail: 'Missing. Set SMARTSPECTRA_API_KEY in .env or the environment.',
      }),
    );
    assert.equal(missing.canStart, false);
    assert.match(missing.reasons[0], /SMARTSPECTRA_API_KEY/);
  });

  it('falls back to a message with the variable name when the doctor detail is empty', () => {
    const gate = setupGate(input({ keyStatus: 'missing', keyDetail: '' }));
    assert.match(gate.reasons[0], /SMARTSPECTRA_API_KEY/);
  });

  it('blocks a failed key check and tells the player where to go', () => {
    const gate = setupGate(input({ keyStatus: 'error' }));
    assert.equal(gate.canStart, false);
    assert.match(gate.reasons[0], /Help/);
  });

  it('blocks while the preview starts and when it fails', () => {
    assert.match(setupGate(input({ preview: 'starting' })).reasons[0], /Starting/);
    assert.match(setupGate(input({ preview: 'idle' })).reasons[0], /Starting/);
    const failed = setupGate(input({ preview: 'error', previewError: 'Camera is busy.' }));
    assert.equal(failed.reasons[0], 'Camera is busy.');
  });

  it('does not start while any one framing check is unknown or failing', () => {
    const partial: FramingChecks = { face: 'pass', chest: 'pass', light: 'unknown' };
    const gate = setupGate(input({ framing: partial }));
    assert.equal(gate.canStart, false);
    assert.match(gate.reasons[0], /Framing/);
    assert.equal(setupGate(input({ framing: waitingFraming })).canStart, false);
  });
});

describe('keyStatusFromChecks', () => {
  it('maps the doctor key row, including a missing detail', () => {
    assert.deepEqual(
      keyStatusFromChecks([
        { id: 'sensing-key', status: 'pass', detail: 'Present (value not shown).' },
      ]),
      { status: 'present', detail: 'Present (value not shown).' },
    );
    assert.equal(
      keyStatusFromChecks([
        {
          id: 'sensing-key',
          status: 'fail',
          detail: 'Missing. Set SMARTSPECTRA_API_KEY in .env or the environment.',
        },
      ]).status,
      'missing',
    );
  });

  it('reports an error when the row is absent, and a fallback detail when it is empty', () => {
    assert.equal(keyStatusFromChecks([]).status, 'error');
    const missing = keyStatusFromChecks([{ id: 'sensing-key', status: 'fail', detail: '' }]);
    assert.equal(missing.status, 'missing');
    assert.match(missing.detail, /SMARTSPECTRA_API_KEY/);
  });
});

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { createElement } from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import type { FramingChecks } from '../shared/framing.js';
import { setupGate, type SetupGateInput } from '../shared/setup.js';
import { SetupScreen, type SetupScreenProps } from './SetupScreen.js';

const readyFraming: FramingChecks = { face: 'pass', chest: 'pass', light: 'pass' };

function gateFor(overrides: Partial<SetupGateInput> = {}) {
  return setupGate({
    consent: true,
    keyStatus: 'present',
    keyDetail: 'Present (value not shown).',
    preview: 'running',
    framing: readyFraming,
    ...overrides,
  });
}

function render(overrides: Partial<SetupScreenProps> = {}): string {
  const props: SetupScreenProps = {
    consent: true,
    keyStatus: 'present',
    keyDetail: 'Present (value not shown).',
    framing: readyFraming,
    framingHint: null,
    preview: 'running',
    previewError: null,
    previewSlot: createElement('div', null, 'Live preview'),
    timeControls: ['1+0', '3+2', '10+0'],
    timeControl: '3+2',
    gate: gateFor(),
    onConsent: () => undefined,
    onTimeControl: () => undefined,
    onStart: () => undefined,
    onBack: () => undefined,
    onHelp: () => undefined,
    ...overrides,
  };
  return renderToStaticMarkup(createElement(SetupScreen, props));
}

describe('SetupScreen markup', () => {
  it('shows all four setup areas and three framing checks', () => {
    const html = render();
    assert.match(html, /1\. Camera and consent/);
    assert.match(html, /2\. Framing/);
    assert.match(html, /3\. Time control/);
    assert.match(html, /One face in view/);
    assert.match(html, /Upper chest visible/);
    assert.match(html, /Enough light/);
    assert.match(html, />Start sensing</);
  });

  it('disables Start until consent and shows the reason', () => {
    const html = render({ consent: false, gate: gateFor({ consent: false }) });
    assert.match(html, /<button[^>]*disabled[^>]*>Start sensing<\/button>/);
    assert.match(html, /Allow the camera to continue/);
  });

  it('shows the missing key variable and no framing preview', () => {
    const html = render({
      keyStatus: 'missing',
      keyDetail: 'Missing. Set SMARTSPECTRA_API_KEY in .env or the environment.',
      preview: 'idle',
      previewSlot: null,
      gate: gateFor({ keyStatus: 'missing', preview: 'idle' }),
    });
    assert.match(html, /SMARTSPECTRA_API_KEY/);
    assert.match(html, /<button[^>]*disabled[^>]*>Start sensing<\/button>/);
    assert.equal(html.includes('Live preview'), false);
  });

  it('keeps Start disabled when one framing check is not passing', () => {
    const framing: FramingChecks = { face: 'pass', chest: 'fail', light: 'unknown' };
    const html = render({
      framing,
      framingHint: 'Sit back so your chest is in frame.',
      gate: gateFor({ framing }),
    });
    assert.match(html, /Framing must pass all three checks/);
    assert.match(html, /Sit back so your chest is in frame\./);
    assert.match(html, /Fix/);
    assert.match(html, /Waiting/);
    assert.match(html, /<button[^>]*disabled[^>]*>Start sensing<\/button>/);
  });

  it('enables Start only when the gate says every check passed', () => {
    const html = render({ gate: gateFor() });
    assert.equal(html.includes('disabled'), false);
    assert.match(html, /All checks pass\. Start when you are ready\./);
  });

  it('exposes every time control as a pressed-state button', () => {
    const html = render();
    for (const control of ['1+0', '3+2', '10+0']) assert.ok(html.includes(`>${control}<`));
    assert.equal((html.match(/aria-pressed="true"/g) ?? []).length, 2);
  });
});

