// What: reads the stored session library for Home and the Sessions screen.
// Why: one corrupt session must not hide every healthy one, and opening must keep games reachable
//      even when a report is stale, newer, or invalid.
// Removed: earlier sessions and their PGNs could not be reached after a restart.
import {
  type Report,
  type SessionOpenResult,
  type SessionReportError,
  type SessionSummary,
} from '../shared/contracts.js';
import {
  StoredReportError,
  hasSavedReport,
  listSessions,
  readGames,
  readMeta,
  readReport,
} from './store.js';

export interface SessionLibraryResult {
  sessions: SessionSummary[];
  unreadable: number;
}

export async function listSessionSummaries(root: string): Promise<SessionLibraryResult> {
  const ids = await listSessions(root);
  const sessions: SessionSummary[] = [];
  let unreadable = 0;
  for (const id of ids) {
    try {
      const meta = await readMeta(root, id);
      const durationMs = meta.stopAnchor
        ? Math.max(0, meta.stopAnchor.monoUs - meta.startAnchor.monoUs) / 1_000
        : null;
      sessions.push({
        id,
        startedAtEpochMs: meta.startedAtEpochMs,
        durationMs,
        coveragePct: meta.coverage?.pct ?? null,
        hasReport: await hasSavedReport(root, id),
      });
    } catch {
      // One unreadable folder is counted, not allowed to break the list.
      unreadable += 1;
    }
  }
  sessions.sort((left, right) => right.startedAtEpochMs - left.startedAtEpochMs);
  return { sessions, unreadable };
}

function reportErrorKind(error: unknown): SessionReportError | null {
  if (!(error instanceof StoredReportError)) return null;
  if (error.kind === 'missing') return null;
  return error.kind;
}

export async function openStoredSession(root: string, sessionId: string): Promise<SessionOpenResult> {
  await readMeta(root, sessionId);
  let report: Report | null = null;
  let reportError: SessionReportError | null = null;
  try {
    report = await readReport(root, sessionId);
  } catch (error) {
    reportError = reportErrorKind(error);
    if (!reportError && !(error instanceof StoredReportError)) throw error;
  }
  let games: string[] = [];
  try {
    games = await readGames(root, sessionId);
  } catch {
    // A missing or invalid PGN batch leaves Games empty and the player can paste again.
    games = [];
  }
  return { report, reportError, games };
}

import assert from 'node:assert/strict';
import { mkdtempSync, rmSync } from 'node:fs';
import { writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { after, describe, it } from 'node:test';
import { createSession, saveGames, saveMeta, saveReport } from './store.js';
import { listSessionSummaries, openStoredSession } from './session-library.js';

const roots: string[] = [];
after(() => {
  for (const root of roots) rmSync(root, { recursive: true, force: true });
});

function useRoot(): string {
  const root = mkdtempSync(path.join(tmpdir(), 'chesspulse-library-'));
  roots.push(root);
  return root;
}

async function makeSession(
  root: string,
  epochMs: number,
  durationMs: number,
  coveragePct: number | null,
): Promise<string> {
  const anchor = { monoUs: 0, epochMs };
  const meta = await createSession(root, { startedAtEpochMs: epochMs, startAnchor: anchor });
  await saveMeta(root, {
    ...meta,
    stopAnchor: { monoUs: durationMs * 1_000, epochMs: epochMs + durationMs },
    stopReason: 'user',
    ...(coveragePct === null
      ? {}
      : {
          coverage: {
            usableUs: durationMs * 1_000 * (coveragePct / 100),
            totalUs: durationMs * 1_000,
            pct: coveragePct,
            confidenceFloor: 50,
          },
        }),
  });
  return meta.id;
}

describe('session library', () => {
  it('lists newest first with duration, coverage, and report presence', async () => {
    const root = useRoot();
    const older = await makeSession(root, 1_700_000_000_000, 60_000, 75);
    const newer = await makeSession(root, 1_700_003_600_000, 120_000, null);
    await saveReport(root, older, '{}');

    const result = await listSessionSummaries(root);
    assert.equal(result.unreadable, 0);
    assert.deepEqual(
      result.sessions.map((session) => session.id),
      [newer, older],
    );
    assert.deepEqual(result.sessions[1], {
      id: older,
      startedAtEpochMs: 1_700_000_000_000,
      durationMs: 60_000,
      coveragePct: 75,
      hasReport: true,
    });
    assert.equal(result.sessions[0].hasReport, false);
    assert.equal(result.sessions[0].coveragePct, null);
  });

  it('counts an unreadable session without hiding the others', async () => {
    const root = useRoot();
    const good = await makeSession(root, 1_700_000_000_000, 10_000, 50);
    const broken = await makeSession(root, 1_700_000_001_000, 10_000, 50);
    await writeFile(path.join(root, 'sessions', broken, 'meta.json'), '{', 'utf8');

    const result = await listSessionSummaries(root);
    assert.equal(result.unreadable, 1);
    assert.deepEqual(result.sessions.map((session) => session.id), [good]);
  });

  it('opens games when there is no report', async () => {
    const root = useRoot();
    const id = await makeSession(root, 1_700_000_000_000, 10_000, 50);
    await saveGames(root, id, ['[Event "first"]']);

    const opened = await openStoredSession(root, id);
    assert.equal(opened.report, null);
    assert.equal(opened.reportError, null);
    assert.deepEqual(opened.games, ['[Event "first"]']);
  });

  it('keeps games reachable when a stored report is invalid, and names the reason', async () => {
    const root = useRoot();
    const id = await makeSession(root, 1_700_000_000_000, 10_000, 50);
    await saveGames(root, id, ['[Event "first"]']);
    await saveReport(root, id, '{}');

    const opened = await openStoredSession(root, id);
    assert.equal(opened.report, null);
    assert.equal(opened.reportError, 'invalid');
    assert.deepEqual(opened.games, ['[Event "first"]']);
  });
});

