// What: the Review refusal summary: the real reason, the coverage numbers when present, and the
// remedy the report builder supplied.
// Why: a refused review must not hide behind a generic "withheld" line.
// Removed: the player would see no reason and no next action.
import type { Refusal } from '../shared/contracts.js';
import { refusalHeading } from '../shared/timeline.js';

export function RefusalPanel({ refusal }: { refusal: Refusal }) {
  const metrics =
    refusal.measured !== undefined && refusal.threshold !== undefined
      ? `Coverage was ${refusal.measured}%; a review needs ${refusal.threshold}%.`
      : null;

  return (
    <div className="refusal-panel" role="alert">
      <h2>{refusalHeading(refusal.reason)}</h2>
      {metrics ? <p className="refusal-metric">{metrics}</p> : null}
      <p>{refusal.remedy}</p>
    </div>
  );
}

// What: the build progress and Cancel control for Review.
// Why: scoring can take minutes and must never be an unresponsive screen.
// Removed: the player could not tell whether the build was moving or how to stop it.
export function ReviewProgress({
  progress,
  cancelling,
  onCancel,
}: {
  progress: { scored: number; total: number } | null;
  cancelling: boolean;
  onCancel(): void;
}) {
  const total = progress?.total ?? 0;
  const scored = progress?.scored ?? 0;
  return (
    <>
      <p aria-live="polite">
        {total > 0
          ? `Scored ${scored} of ${total} positions…`
          : 'Scoring positions locally with Stockfish…'}
      </p>
      {total > 0 ? (
        <progress
          className="report-progress"
          aria-label="Positions scored"
          value={scored}
          max={total}
        />
      ) : null}
      <button type="button" onClick={onCancel} disabled={cancelling}>
        {cancelling ? 'Cancelling…' : 'Cancel report'}
      </button>
    </>
  );
}

